using System.Collections.Generic;
using UnityEngine;

namespace Eco.Scripts.Hats
{
    [CreateAssetMenu(menuName = "Eco/HatCatalogue")]
    public class HatCatalogue : ScriptableObject
    {
        [SerializeField] private List<HatBuyUpgrade> hatUpgrades = new();

        public List<HatBuyUpgrade> HatUpgrades => hatUpgrades;

        public HatBuyUpgrade GetHatUpgradeById(string id)
        {
            return hatUpgrades.Find(x => x.upgradeId == id);
        }

        public int GetHatCount()
        {
            return hatUpgrades.Count;
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Eco.Scripts.Pooling;
using Eco.Scripts.Upgrades;
using Unity.AI.Navigation;
using UnityEngine;
using VContainer;

namespace Eco.Scripts.World
{
    public class WorldController : MonoBehaviour
    {
        [SerializeField] List<ChunkPrefab> chunkPrefabs;
        [SerializeField] Transform player;
        [SerializeField] WaterChunk waterPrefab;
        [SerializeField] int renderRadius = 5; // how many chunks in each direction from the player
        [SerializeField] private NavMeshSurface navMeshPlane;

        private WorldPreset _worldPreset;
        private readonly Dictionary<Vector2Int, Chunk> _spawnedChunks = new();
        private Vector2Int _currentPlayerChunkCoord;
        private SaveManager _saveManager;

        private bool _initialized;
        private TreePlanter _treePlanter;
        private UpgradesCollection _upgrades;
        private CurrencyManager _currencyManager;
        private PileScoreUpgrade _pileScoreUpgrade;
        private DigPowerUpgrade _digPowerUpgrade;

        public const int ChunkSize = 10;
        public int RenderRadius => renderRadius;
        public TreePlanter TreePlanter => _treePlanter;
        public Dictionary<Vector2Int, Chunk> ActiveChunks => _spawnedChunks;

        public int WorldSideSize => _worldPreset.WorldSideSize;
        public int WorldSize => WorldSideSize * 2 + 1;

        private readonly Dictionary<ChunkType, ObjectPool<Chunk>> _pools = new();

        [Inject]
        public void Initialize(SaveManager saveManager, UpgradesCollection upgrades, CurrencyManager currencyManager)
        {
            _saveManager = saveManager;
            _upgrades = upgrades;
            _currencyManager = currencyManager;
        }

        public void SpawnWorld(WorldPreset worldPreset)
        {
            _worldPreset = worldPreset;
            _worldPreset.GenerateMap();
            foreach (var chunkPrefab in chunkPrefabs)
            {
                //always create water pool
                if (!_worldPreset.ChunkTypes.Contains(chunkPrefab.type) && chunkPrefab.type != ChunkType.Water)
                {
                    continue;
                }

                _pools[chunkPrefab.type] = chunkPrefab.CreatePool(renderRadius * renderRadius, transform);
            }


            _treePlanter = new TreePlanter(_upgrades, player, this);
            _treePlanter.Init();

            // Get the PileScoreUpgrade from upgrades collection
            _pileScoreUpgrade = _upgrades.GetUpgradeType<PileScoreUpgrade>();
            _digPowerUpgrade = _upgrades.GetUpgradeType<DigPowerUpgrade>();

            Flatten();
            RebuildNavMesh();
            UpdateWorld();
            _initialized = true;
         }

        private void RebuildNavMesh()
        {
            navMeshPlane.BuildNavMesh();
        }

        void Update()
         {
             if (!_initialized)
             {
                 return;
             }

             Vector2Int newChunkCoord = GetPlayerChunkCoord();
             if (newChunkCoord != _currentPlayerChunkCoord)
             {
                 _currentPlayerChunkCoord = newChunkCoord;
                 UpdateWorld();
             }
         }

         public Vector2Int GetPlayerChunkCoord()
         {
             int x = Mathf.FloorToInt(player.position.x / ChunkSize);
             int z = Mathf.FloorToInt(player.position.z / ChunkSize);
             return new Vector2Int(x, z);
         }

         private void UpdateWorld()
         {
             Vector2Int center = GetPlayerChunkCoord();
             HashSet<Vector2Int> neededChunks = new();

             // Spawn chunks in render radius
             for (int x = -renderRadius; x <= renderRadius; x++)
             {
                 for (int z = -renderRadius; z <= renderRadius; z++)
                 {
                     Vector2Int coord = new Vector2Int(center.x + x, center.y + z);
                     neededChunks.Add(coord);

                     if (!_spawnedChunks.ContainsKey(coord))
                     {
                         Vector3 pos = new Vector3(coord.x * ChunkSize, 0, coord.y * ChunkSize);
                        var type = _worldPreset.GetChunkType(coord);
                         Chunk chunk = _pools[type].Get();
                         chunk.Setup(coord, _saveManager, _worldPreset.TrashPerChunk);

                         if(type == ChunkType.Water)
                         {
                             WaterChunk waterChunk = (WaterChunk)chunk;
                             waterChunk.Init();
                             waterChunk.UpdateWaterCorners(WorldSideSize, coord);
                             pos.y = -1;
                         }
                         else if(type == ChunkType.Field)
                         {
                             FieldChunk fieldChunk = (FieldChunk)chunk;
                             fieldChunk.Init(_treePlanter);
                         } else if (type == ChunkType.Pile)
                         {
                             PileChunk pileChunk = (PileChunk)chunk;
                             pileChunk.Init(_currencyManager, _pileScoreUpgrade, _digPowerUpgrade, _worldPreset.Difficulty);
                         }

                         chunk.transform.parent = transform;
                         chunk.transform.position = pos;
                         chunk.transform.rotation = Quaternion.identity;

                         chunk.name = $"{type}_Chunk_{coord.x}_{coord.y}";
                         _spawnedChunks[coord] = chunk;
                     }
                 }
             }

             //remove far-away chunks
             List<Vector2Int> toRemove = new();
             foreach (var chunkCoord in _spawnedChunks.Keys)
             {
                 if (!neededChunks.Contains(chunkCoord))
                 {
                     toRemove.Add(chunkCoord);
                 }
             }

             foreach (var coord in toRemove)
             {
                 var chunk = _spawnedChunks[coord];
                 chunk.SaveTiles();

                 _pools[chunk.Type].ReturnToPool(chunk);
                 _spawnedChunks.Remove(coord);
             }
         }

         public void Flatten()
         {
             var terrain = Terrain.activeTerrain;
             TerrainData data = terrain.terrainData;

             int heightmapWidth = data.heightmapResolution;
             int heightmapHeight = data.heightmapResolution;

             float[,] heights = data.GetHeights(0, 0, heightmapWidth, heightmapHeight);

             float terrainWidth = data.size.x;
             float terrainLength = data.size.z;
             float maxHeight = data.size.y;

             var size = WorldSize * 10;
             float centerHalf = size / 2f;
             float centerX = terrainWidth / 2f;
             float centerZ = terrainLength / 2f;

             float normalizedCenterHeight = 10 / maxHeight;
             float normalizedBorderHeight = 0 / maxHeight;

             float falloff = 50;

             for (int y = 0; y < heightmapHeight; y++)
             {
                 for (int x = 0; x < heightmapWidth; x++)
                 {
                     float worldX = (x / (float)(heightmapWidth - 1)) * terrainWidth;
                     float worldZ = (y / (float)(heightmapHeight - 1)) * terrainLength;

                     // Distance from center of terrain
                     float dx = Mathf.Abs(worldX - centerX);
                     float dz = Mathf.Abs(worldZ - centerZ);
                     float distanceFromEdge = Mathf.Max(dx - centerHalf, dz - centerHalf);

                     if (distanceFromEdge <= 0)
                     {
                         // Inside plateau
                         heights[y, x] = normalizedCenterHeight;
                     }
                     else if (distanceFromEdge >= falloff)
                     {
                         // Fully outside plateau
                         heights[y, x] = normalizedBorderHeight;
                     }
                     else
                     {
                         // In falloff zone — blend smoothly
                         float t = Mathf.InverseLerp(0, falloff, distanceFromEdge);
                         heights[y, x] = Mathf.Lerp(normalizedCenterHeight, normalizedBorderHeight, t);
                     }
                 }
             }

             data.SetHeights(0, 0, heights);
         }

         public void SaveWorld()
         {
             foreach (var field in _spawnedChunks.Values)
             {
                 field.SaveTiles();
             }
         }

         private void OnDestroy()
         {
             _treePlanter?.Clear();
         }

         [System.Serializable]
         private class ChunkPrefab
         {
             public ChunkType type;
             public Chunk chunk;

             public ObjectPool<Chunk> CreatePool(int initialSize, Transform parent)
             {
                 return new ObjectPool<Chunk>(chunk, initialSize, parent);
             }
         }
     }
 }

using System.Collections.Generic;
using System.Linq;
using Eco.Scripts.Pooling;
using Eco.Scripts.Upgrades;
using Unity.AI.Navigation;
using UnityEngine;
using VContainer;

namespace Eco.Scripts.World
{
    public class WorldController : MonoBehaviour
    {
        [SerializeField] List<ChunkPrefab> chunkPrefabs;
        [SerializeField] Transform player;
        [SerializeField] WaterChunk waterPrefab;
        [SerializeField] int renderRadius = 5; // how many chunks in each direction from the player
        [SerializeField] private NavMeshSurface navMeshPlane;

        private WorldPreset _worldPreset;
        private readonly Dictionary<Vector2Int, Chunk> _spawnedChunks = new();
        private Vector2Int _currentPlayerChunkCoord;
        private SaveManager _saveManager;

        private bool _initialized;
        private TreePlanter _treePlanter;
        private UpgradesCollection _upgrades;
        private CurrencyManager _currencyManager;
        private PileScoreUpgrade _pileScoreUpgrade;
        private DigPowerUpgrade _digPowerUpgrade;

        public const int ChunkSize = 10;
        public int RenderRadius => renderRadius;
        public TreePlanter TreePlanter => _treePlanter;
        public Dictionary<Vector2Int, Chunk> ActiveChunks => _spawnedChunks;

        public int WorldSideSize => _worldPreset.WorldSideSize;
        public int WorldSize => WorldSideSize * 2 + 1;

        private readonly Dictionary<ChunkType, ObjectPool<Chunk>> _pools = new();

        [Inject]
        public void Initialize(SaveManager saveManager, UpgradesCollection upgrades, CurrencyManager currencyManager)
        {
            _saveManager = saveManager;
            _upgrades = upgrades;
            _currencyManager = currencyManager;
        }

        public void SpawnWorld(WorldPreset worldPreset)
        {
            _worldPreset = worldPreset;
            _worldPreset.GenerateMap();
            foreach (var chunkPrefab in chunkPrefabs)
            {
                //always create water and beach pools
                if (!_worldPreset.ChunkTypes.Contains(chunkPrefab.type) && 
                    chunkPrefab.type != ChunkType.Water && 
                    chunkPrefab.type != ChunkType.Beach)
                {
                    continue;
                }

                _pools[chunkPrefab.type] = chunkPrefab.CreatePool(renderRadius * renderRadius, transform);
            }


            _treePlanter = new TreePlanter(_upgrades, player, this);
            _treePlanter.Init();

            // Get the PileScoreUpgrade from upgrades collection
            _pileScoreUpgrade = _upgrades.GetUpgradeType<PileScoreUpgrade>();
            _digPowerUpgrade = _upgrades.GetUpgradeType<DigPowerUpgrade>();

            Flatten();
            RebuildNavMesh();
            UpdateWorld();
            _initialized = true;
         }

        private void RebuildNavMesh()
        {
            navMeshPlane.BuildNavMesh();
        }

        void Update()
         {
             if (!_initialized)
             {
                 return;
             }

             Vector2Int newChunkCoord = GetPlayerChunkCoord();
             if (newChunkCoord != _currentPlayerChunkCoord)
             {
                 _currentPlayerChunkCoord = newChunkCoord;
                 UpdateWorld();
             }
         }

         public Vector2Int GetPlayerChunkCoord()
         {
             int x = Mathf.FloorToInt(player.position.x / ChunkSize);
             int z = Mathf.FloorToInt(player.position.z / ChunkSize);
             return new Vector2Int(x, z);
         }

         private void UpdateWorld()
         {
             Vector2Int center = GetPlayerChunkCoord();
             HashSet<Vector2Int> neededChunks = new();

             // Spawn chunks in render radius
             for (int x = -renderRadius; x <= renderRadius; x++)
             {
                 for (int z = -renderRadius; z <= renderRadius; z++)
                 {
                     Vector2Int coord = new Vector2Int(center.x + x, center.y + z);
                     neededChunks.Add(coord);

                     if (!_spawnedChunks.ContainsKey(coord))
                     {
                         Vector3 pos = new Vector3(coord.x * ChunkSize, 0, coord.y * ChunkSize);
                        var type = _worldPreset.GetChunkType(coord);
                         Chunk chunk = _pools[type].Get();
                         chunk.Setup(coord, _saveManager, _worldPreset.TrashPerChunk);

                         if(type == ChunkType.Water)
                         {
                             WaterChunk waterChunk = (WaterChunk)chunk;
                             waterChunk.Init();
                             waterChunk.UpdateWaterCorners(WorldSideSize, coord);
                             pos.y = -1;
                         }
                         else if(type == ChunkType.Field)
                         {
                             FieldChunk fieldChunk = (FieldChunk)chunk;
                             fieldChunk.Init(_treePlanter);
                         } 
                         else if (type == ChunkType.Pile)
                         {
                             PileChunk pileChunk = (PileChunk)chunk;
                             pileChunk.Init(_currencyManager, _pileScoreUpgrade, _digPowerUpgrade, _worldPreset.Difficulty);
                         }
                         else if (type == ChunkType.Beach)
                         {
                             BeachChunk beachChunk = (BeachChunk)chunk;
                             beachChunk.Init();
                         }

                         chunk.transform.parent = transform;
                         chunk.transform.position = pos;
                         chunk.transform.rotation = Quaternion.identity;

                         chunk.name = $"{type}_Chunk_{coord.x}_{coord.y}";
                         _spawnedChunks[coord] = chunk;
                     }
                 }
             }

             //remove far-away chunks
             List<Vector2Int> toRemove = new();
             foreach (var chunkCoord in _spawnedChunks.Keys)
             {
                 if (!neededChunks.Contains(chunkCoord))
                 {
                     toRemove.Add(chunkCoord);
                 }
             }

             foreach (var coord in toRemove)
             {
                 var chunk = _spawnedChunks[coord];
                 chunk.SaveTiles();

                 _pools[chunk.Type].ReturnToPool(chunk);
                 _spawnedChunks.Remove(coord);
             }
         }

         public void Flatten()
         {
             var terrain = Terrain.activeTerrain;
             TerrainData data = terrain.terrainData;

             int heightmapWidth = data.heightmapResolution;
             int heightmapHeight = data.heightmapResolution;

             float[,] heights = data.GetHeights(0, 0, heightmapWidth, heightmapHeight);

             float terrainWidth = data.size.x;
             float terrainLength = data.size.z;
             float maxHeight = data.size.y;

             var size = WorldSize * 10;
             float centerHalf = size / 2f;
             float centerX = terrainWidth / 2f;
             float centerZ = terrainLength / 2f;

             float normalizedCenterHeight = 10 / maxHeight;
             float normalizedBorderHeight = 0 / maxHeight;

             float falloff = 50;

             for (int y = 0; y < heightmapHeight; y++)
             {
                 for (int x = 0; x < heightmapWidth; x++)
                 {
                     float worldX = (x / (float)(heightmapWidth - 1)) * terrainWidth;
                     float worldZ = (y / (float)(heightmapHeight - 1)) * terrainLength;

                     // Distance from center of terrain
                     float dx = Mathf.Abs(worldX - centerX);
                     float dz = Mathf.Abs(worldZ - centerZ);
                     float distanceFromEdge = Mathf.Max(dx - centerHalf, dz - centerHalf);

                     if (distanceFromEdge <= 0)
                     {
                         // Inside plateau
                         heights[y, x] = normalizedCenterHeight;
                     }
                     else if (distanceFromEdge >= falloff)
                     {
                         // Fully outside plateau
                         heights[y, x] = normalizedBorderHeight;
                     }
                     else
                     {
                         // In falloff zone — blend smoothly
                         float t = Mathf.InverseLerp(0, falloff, distanceFromEdge);
                         heights[y, x] = Mathf.Lerp(normalizedCenterHeight, normalizedBorderHeight, t);
                     }
                 }
             }

             data.SetHeights(0, 0, heights);
         }

         public void SaveWorld()
         {
             foreach (var field in _spawnedChunks.Values)
             {
                 field.SaveTiles();
             }
         }

         private void OnDestroy()
         {
             _treePlanter?.Clear();
         }

         [System.Serializable]
         private class ChunkPrefab
         {
             public ChunkType type;
             public Chunk chunk;

             public ObjectPool<Chunk> CreatePool(int initialSize, Transform parent)
             {
                 return new ObjectPool<Chunk>(chunk, initialSize, parent);
             }
         }
     }
 }

using System.Collections.Generic;
using System.Linq;
using Eco.Scripts.Trash;
using UnityEngine;

namespace Eco.Scripts.World
{
    [CreateAssetMenu(menuName = "Eco/WorldPreset", fileName = "WorldPreset")]
    public class WorldPreset : ScriptableObject
    {
        [SerializeField] private string worldId;
        [SerializeField] private int worldSideSize = 10;
        [SerializeField] private int seed = 5;
        [SerializeField] private int trashPerChunk = 3;
        [SerializeField] private int difficulty = 1;
        [SerializeField] private ChunkType[] chunkTypes = new[] { ChunkType.Water };

        [SerializeField] private List<TrashItem> allowedTrashItems;

        // Rules asset that controls adjacency, min/max and weights for chunk generation
        [SerializeField] private ChunkGenerationRules generationRules;

        public int WorldSideSize => worldSideSize;
        public ChunkType[] ChunkTypes => chunkTypes;
        public string WorldId => worldId;
        public int TrashPerChunk => trashPerChunk;

        public int Difficulty => difficulty;
        public List<TrashItem> AllowedTrashItems => allowedTrashItems;
        private Dictionary<Vector2Int, ChunkType> _map = new();

        public void GenerateMap()
        {
            _map = new Dictionary<Vector2Int, ChunkType>();

            Random.InitState(seed);

            // Build coordinate list and shuffle it to avoid directional bias
            var coords = new List<Vector2Int>();
            for (int x = -worldSideSize; x <= worldSideSize; x++)
            {
                for (int y = -worldSideSize; y <= worldSideSize; y++)
                {
                    coords.Add(new Vector2Int(x, y));
                }
            }

            // Fisher-Yates shuffle
            for (int i = coords.Count - 1; i > 0; i--)
            {
                int j = Random.Range(0, i + 1);
                var tmp = coords[i];
                coords[i] = coords[j];
                coords[j] = tmp;
            }

            // Counters for placed types
            var counters = new Dictionary<ChunkType, int>();
            foreach (var t in chunkTypes)
            {
                counters[t] = 0;
            }

            // Place tiles in shuffled order with respect to rules
            foreach (var coord in coords)
            {
                var candidates = GetValidCandidates(coord, counters);

                ChunkType chosen;
                if (candidates.Count == 0)
                {
                    // Relaxation: allow any chunk type from pool that hasn't hit its max
                    var fallback = chunkTypes.Where(t => !HasReachedMax(counters, t)).ToList();
                    if (fallback.Count == 0)
                    {
                        // Everything reached max or pool empty - use first available in pool (honor user's config)
                        chosen = chunkTypes.Length > 0 ? chunkTypes[0] : ChunkType.Water;
                    }
                    else
                    {
                        chosen = fallback[Random.Range(0, fallback.Count)];
                    }
                }
                else
                {
                    // Weighted random pick among candidates
                    int totalWeight = candidates.Sum(c => c.Rule.weight);
                    int pick = totalWeight <= 0 ? 0 : Random.Range(0, totalWeight);
                    int acc = 0;
                    chosen = candidates[0].Type; // default
                    foreach (var c in candidates)
                    {
                        acc += Mathf.Max(0, c.Rule.weight);
                        if (pick < acc)
                        {
                            chosen = c.Type;
                            break;
                        }
                    }
                }

                _map[coord] = chosen;
                if (counters.ContainsKey(chosen)) counters[chosen]++;
                else counters[chosen] = 1;
            }

            // Try to satisfy MinCount constraints by attempting to replace tiles where possible
            RepairMinimums(counters, coords);
        }

        private struct Candidate
        {
            public ChunkType Type;
            public ChunkGenerationRules.ChunkRule Rule;
        }

        private List<Candidate> GetValidCandidates(Vector2Int coord, Dictionary<ChunkType, int> counters)
        {
            var list = new List<Candidate>();
            foreach (var type in chunkTypes)
            {
                var rule = generationRules.GetRule(type);

                // Check max
                if (HasReachedMax(counters, type, rule))
                    continue;

                // Check adjacency against already placed neighbors
                if (!IsAllowedByNeighbors(coord, type))
                    continue;

                list.Add(new Candidate { Type = type, Rule = rule });
            }

            return list;
        }

        private bool HasReachedMax(Dictionary<ChunkType, int> counters, ChunkType type,
            ChunkGenerationRules.ChunkRule rule = null)
        {
            if (rule == null) rule = generationRules.GetRule(type);
            counters.TryGetValue(type, out var count);
            return count >= rule.maxCount;
        }

        private bool IsAllowedByNeighbors(Vector2Int coord, ChunkType candidate)
        {
            // check 4-neighbors only
            Vector2Int[] neighbors =
            {
                new Vector2Int(coord.x + 1, coord.y),
                new Vector2Int(coord.x - 1, coord.y),
                new Vector2Int(coord.x, coord.y + 1),
                new Vector2Int(coord.x, coord.y - 1),
            };

            var candidateRule = generationRules.GetRule(candidate);

            foreach (var n in neighbors)
            {
                if (!_map.TryGetValue(n, out var neighborType)) continue; // neighbor not placed yet - fine

                // If candidate has an AllowedAdjacent list, neighborType must be in it
                if (candidateRule.allowedAdjacent != null && candidateRule.allowedAdjacent.Length > 0)
                {
                    if (!candidateRule.allowedAdjacent.Contains(neighborType))
                        return false;
                }

                // Additionally, if neighbor has a rule, it should allow candidate (if it has restrictions)
                var neighborRule = generationRules.GetRule(neighborType);
                if (neighborRule.allowedAdjacent != null && neighborRule.allowedAdjacent.Length > 0)
                {
                    if (!neighborRule.allowedAdjacent.Contains(candidate))
                        return false;
                }
            }

            return true;
        }

        private void RepairMinimums(Dictionary<ChunkType, int> counters, List<Vector2Int> coords)
        {
            // For each rule that is below its min, attempt to replace some other tiles
            // Only consider rules for types that are present in this preset's chunkTypes array.
            foreach (var rule in generationRules.Rules.Where(r => chunkTypes.Contains(r.type)))
            {
                counters.TryGetValue(rule.type, out var current);
                if (current >= rule.minCount) continue;

                int need = rule.minCount - current;

                // Try to find replaceable coords (where changing the type to rule.Type won't violate neighbor rules and won't break max constraints)
                var replaceable = new List<Vector2Int>();

                foreach (var coord in coords)
                {
                    if (!_map.TryGetValue(coord, out var existing)) continue;
                    if (existing == rule.type) continue;

                    // Skip if target type reached its max
                    if (HasReachedMax(counters, rule.type, rule)) break;

                    // Temporarily remove existing to test adjacency
                    var prev = _map[coord];
                    _map.Remove(coord);

                    bool canPlace = IsAllowedByNeighbors(coord, rule.type);

                    // restore
                    _map[coord] = prev;

                    if (canPlace)
                        replaceable.Add(coord);

                    if (replaceable.Count >= need) break;
                }

                // Perform replacements up to 'need'
                int replaced = 0;
                foreach (var rc in replaceable)
                {
                    if (replaced >= need) break;

                    var old = _map[rc];
                    // Remove and test again for safety
                    _map.Remove(rc);
                    if (IsAllowedByNeighbors(rc, rule.type))
                    {
                        _map[rc] = rule.type;

                        // update counters
                        if (counters.ContainsKey(old)) counters[old] = MathMax(0, counters[old] - 1);
                        counters[rule.type] = counters.TryGetValue(rule.type, out var val) ? val + 1 : 1;

                        replaced++;
                    }
                    else
                    {
                        // restore original
                        _map[rc] = old;
                    }
                }

                // If we couldn't reach the minimum, we leave as-is (honor constraints best-effort)
            }
        }

        // small helper to avoid System.Math dependency
        private int MathMax(int a, int b) => a > b ? a : b;

        public ChunkType GetChunkType(Vector2Int coord)
        {
            return _map.GetValueOrDefault(coord, ChunkType.Water);
        }
    }
}

using System.Collections.Generic;
using System.Linq;
using Eco.Scripts.Trash;
using UnityEngine;

namespace Eco.Scripts.World
{
    [CreateAssetMenu(menuName = "Eco/WorldPreset", fileName = "WorldPreset")]
    public class WorldPreset : ScriptableObject
    {
        [SerializeField] private string worldId;
        [SerializeField] private int worldSideSize = 10;
        [SerializeField] private int seed = 5;
        [SerializeField] private int trashPerChunk = 3;
        [SerializeField] private int difficulty = 1;
        [SerializeField] private ChunkType[] chunkTypes = new[] { ChunkType.Water };

        [SerializeField] private List<TrashItem> allowedTrashItems;

        // Rules asset that controls adjacency, min/max and weights for chunk generation
        [SerializeField] private ChunkGenerationRules generationRules;

        public int WorldSideSize => worldSideSize;
        public ChunkType[] ChunkTypes => chunkTypes;
        public string WorldId => worldId;
        public int TrashPerChunk => trashPerChunk;

        public int Difficulty => difficulty;
        public List<TrashItem> AllowedTrashItems => allowedTrashItems;
        private Dictionary<Vector2Int, ChunkType> _map = new();

        public void GenerateMap()
        {
            _map = new Dictionary<Vector2Int, ChunkType>();

            Random.InitState(seed);

            // Build coordinate list and shuffle it to avoid directional bias
            var coords = new List<Vector2Int>();
            var borderCoords = new List<Vector2Int>();

            for (int x = -worldSideSize; x <= worldSideSize; x++)
            {
                for (int y = -worldSideSize; y <= worldSideSize; y++)
                {
                    var coord = new Vector2Int(x, y);

                    // Check if this coordinate is on the border (edge of playable area)
                    bool isBorder = x == -worldSideSize || x == worldSideSize || 
                                   y == -worldSideSize || y == worldSideSize;

                    if (isBorder)
                    {
                        // Place Beach chunks on the border
                        _map[coord] = ChunkType.Beach;
                        borderCoords.Add(coord);
                    }
                    else
                    {
                        coords.Add(coord);
                    }
                }
            }

            // Fisher-Yates shuffle for non-border coords
            for (int i = coords.Count - 1; i > 0; i--)
            {
                int j = Random.Range(0, i + 1);
                var tmp = coords[i];
                coords[i] = coords[j];
                coords[j] = tmp;
            }

            // Counters for placed types
            var counters = new Dictionary<ChunkType, int>();
            foreach (var t in chunkTypes)
            {
                counters[t] = 0;
            }

            // Add beach count
            counters[ChunkType.Beach] = borderCoords.Count;

            // Place tiles in shuffled order with respect to rules (only for non-border coords)
            foreach (var coord in coords)
            {
                var candidates = GetValidCandidates(coord, counters);

                ChunkType chosen;
                if (candidates.Count == 0)
                {
                    // Relaxation: allow any chunk type from pool that hasn't hit its max
                    var fallback = chunkTypes.Where(t => !HasReachedMax(counters, t)).ToList();
                    if (fallback.Count == 0)
                    {
                        // Everything reached max or pool empty - use first available in pool (honor user's config)
                        chosen = chunkTypes.Length > 0 ? chunkTypes[0] : ChunkType.Water;
                    }
                    else
                    {
                        chosen = fallback[Random.Range(0, fallback.Count)];
                    }
                }
                else
                {
                    // Weighted random pick among candidates
                    int totalWeight = candidates.Sum(c => c.Rule.weight);
                    int pick = totalWeight <= 0 ? 0 : Random.Range(0, totalWeight);
                    int acc = 0;
                    chosen = candidates[0].Type; // default
                    foreach (var c in candidates)
                    {
                        acc += Mathf.Max(0, c.Rule.weight);
                        if (pick < acc)
                        {
                            chosen = c.Type;
                            break;
                        }
                    }
                }

                _map[coord] = chosen;
                if (counters.ContainsKey(chosen)) counters[chosen]++;
                else counters[chosen] = 1;
            }

            // Try to satisfy MinCount constraints by attempting to replace tiles where possible
            RepairMinimums(counters, coords);
        }

        private struct Candidate
        {
            public ChunkType Type;
            public ChunkGenerationRules.ChunkRule Rule;
        }

        private List<Candidate> GetValidCandidates(Vector2Int coord, Dictionary<ChunkType, int> counters)
        {
            var list = new List<Candidate>();
            foreach (var type in chunkTypes)
            {
                var rule = generationRules.GetRule(type);

                // Check max
                if (HasReachedMax(counters, type, rule))
                    continue;

                // Check adjacency against already placed neighbors
                if (!IsAllowedByNeighbors(coord, type))
                    continue;

                list.Add(new Candidate { Type = type, Rule = rule });
            }

            return list;
        }

        private bool HasReachedMax(Dictionary<ChunkType, int> counters, ChunkType type,
            ChunkGenerationRules.ChunkRule rule = null)
        {
            if (rule == null) rule = generationRules.GetRule(type);
            counters.TryGetValue(type, out var count);
            return count >= rule.maxCount;
        }

        private bool IsAllowedByNeighbors(Vector2Int coord, ChunkType candidate)
        {
            // check 4-neighbors only
            Vector2Int[] neighbors =
            {
                new Vector2Int(coord.x + 1, coord.y),
                new Vector2Int(coord.x - 1, coord.y),
                new Vector2Int(coord.x, coord.y + 1),
                new Vector2Int(coord.x, coord.y - 1),
            };

            var candidateRule = generationRules.GetRule(candidate);

            foreach (var n in neighbors)
            {
                if (!_map.TryGetValue(n, out var neighborType)) continue; // neighbor not placed yet - fine

                // If candidate has an AllowedAdjacent list, neighborType must be in it
                if (candidateRule.allowedAdjacent != null && candidateRule.allowedAdjacent.Length > 0)
                {
                    if (!candidateRule.allowedAdjacent.Contains(neighborType))
                        return false;
                }

                // Additionally, if neighbor has a rule, it should allow candidate (if it has restrictions)
                var neighborRule = generationRules.GetRule(neighborType);
                if (neighborRule.allowedAdjacent != null && neighborRule.allowedAdjacent.Length > 0)
                {
                    if (!neighborRule.allowedAdjacent.Contains(candidate))
                        return false;
                }
            }

            return true;
        }

        private void RepairMinimums(Dictionary<ChunkType, int> counters, List<Vector2Int> coords)
        {
            // For each rule that is below its min, attempt to replace some other tiles
            // Only consider rules for types that are present in this preset's chunkTypes array.
            foreach (var rule in generationRules.Rules.Where(r => chunkTypes.Contains(r.type)))
            {
                counters.TryGetValue(rule.type, out var current);
                if (current >= rule.minCount) continue;

                int need = rule.minCount - current;

                // Try to find replaceable coords (where changing the type to rule.Type won't violate neighbor rules and won't break max constraints)
                var replaceable = new List<Vector2Int>();

                foreach (var coord in coords)
                {
                    if (!_map.TryGetValue(coord, out var existing)) continue;
                    if (existing == rule.type) continue;

                    // Skip if target type reached its max
                    if (HasReachedMax(counters, rule.type, rule)) break;

                    // Temporarily remove existing to test adjacency
                    var prev = _map[coord];
                    _map.Remove(coord);

                    bool canPlace = IsAllowedByNeighbors(coord, rule.type);

                    // restore
                    _map[coord] = prev;

                    if (canPlace)
                        replaceable.Add(coord);

                    if (replaceable.Count >= need) break;
                }

                // Perform replacements up to 'need'
                int replaced = 0;
                foreach (var rc in replaceable)
                {
                    if (replaced >= need) break;

                    var old = _map[rc];
                    // Remove and test again for safety
                    _map.Remove(rc);
                    if (IsAllowedByNeighbors(rc, rule.type))
                    {
                        _map[rc] = rule.type;

                        // update counters
                        if (counters.ContainsKey(old)) counters[old] = MathMax(0, counters[old] - 1);
                        counters[rule.type] = counters.TryGetValue(rule.type, out var val) ? val + 1 : 1;

                        replaced++;
                    }
                    else
                    {
                        // restore original
                        _map[rc] = old;
                    }
                }

                // If we couldn't reach the minimum, we leave as-is (honor constraints best-effort)
            }
        }

        // small helper to avoid System.Math dependency
        private int MathMax(int a, int b) => a > b ? a : b;

        public ChunkType GetChunkType(Vector2Int coord)
        {
            return _map.GetValueOrDefault(coord, ChunkType.Water);
        }
    }
}

